def top_k(lst, k):
    if k <= 0:
        return []
    sort, output = [], []
    while lst:
        largest = lst[0]
        for i in lst:
            if i > largest:
                largest = i
        lst.remove(largest)
        sort.append(largest)
    for j in sort:
        output.append(j)
        if len(output) == k:
            break
    return output

